// caches, build output, and other VCS metadata. They never contain a repo we
// want to surface and can hold tens of thousands of files.
const SCAN_IGNORE_DIRS = new Set([
	'node_modules',
	'.git',
	'.svn',
	'.hg',
	'dist',
	'build',
	'out',
	'target',
	'.next',
	'.turbo',
	'.cache',
	'.venv',
	'venv',
