export type { ContextTab };

// Per-file pending composer state — keyed by `${filePath}::${side}::${line}`.
// Used by DiffFileSection to render an inline compose box at the right spot.
export interface PendingComposer {
	filePath: string;
	line: number;
	side: 'LEFT' | 'RIGHT';
